/**
 * @param list<Token> $tokensToInsert
 * @param list<string> $insertedAttributesContent
 */
private static function isAttributeAlreadyPresent(Tokens $tokens, int $index, array $tokensToInsert, array $insertedAttributesContent): bool
{
    $attributeIndex = $tokens->getNextMeaningfulToken($index);
    if (!$tokens[$attributeIndex]->isGivenKind(T_ATTRIBUTE)) {
        return false;
    }

    $insertedClassName = '';
    foreach (\array_slice($tokensToInsert, 3) as $token) {
        if ($token->equals('(') || $token->isGivenKind(CT::T_ATTRIBUTE_CLOSE)) {
            break;
        }
        $insertedClassName .= $token->getContent();
    }

    static $phpUnitAttributesFixer = null;
    if (null === $phpUnitAttributesFixer) {
        $phpUnitAttributesFixer = new self();
    }

    foreach (AttributeAnalyzer::collect($tokens, $attributeIndex) as $attributeAnalysis) {
        foreach ($attributeAnalysis->getAttributes() as $attribute) {
            $attributeContent = self::getTokensContent(
                \array_slice($tokens->toArray(), $attribute['start'], $attribute['end'] - $attribute['start'] + 1),
            );

            if (\in_array($attributeContent, $insertedAttributesContent, true)) {
                continue;
            }

            $className = ltrim($phpUnitAttributesFixer->determineAttributeFullyQualifiedName(
                $tokens,
                $attribute['name'],
                $attribute['start'],
            ), '\\');

            if ($insertedClassName === $className) {
                return true;
            }
        }
    }

    return false;
}

/**
 * @param list<Token> $tokens
 */
private static function getTokensContent(array $tokens): string
{
    return implode('', array_map(static fn (Token $token): string => $token->getContent(), $tokens));
}

