    }

    $startIndex = $index;
    $prevIndex = $tokens->getPrevMeaningfulToken($index);

    if ($tokens[$tokens->getPrevMeaningfulToken($index)]->isGivenKind(CT::T_ATTRIBUTE_CLOSE)) {
