        if ($tokens[$index]->equals('(')) {
            $index = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $index);
            $index = $tokens->getNextTokenOfKind($index, [',', [CT::T_ATTRIBUTE_CLOSE]]);
        }

        $elements[] = [
            'start' => $attributeStartIndex,
            'end' => $index - 1,
            'name' => $attributeName,
        ];

        $nextIndex = $index;

